#include <iostream>

// Function prototype (forward declaration)
int maximum(int x, int y, int z);

int main() {
    int a = 0, b = 0, c = 0;
    if (std::cin >> a >> b >> c) {
        std::cout << "Maximum is: " << maximum(a, b, c) << "\n";
    }
    return 0;
}

// Function definition
int maximum(int x, int y, int z) {
    int maxVal = x;
    if (y > maxVal) {
        maxVal = y;
    }
    if (z > maxVal) {
        maxVal = z;
    }
    return maxVal;
}

#include <iostream>
#include <cmath>

// Expects double, returns double
double computeHypotenuse(double a, double b) {
    return std::sqrt(a * a + b * b);
}

// Demonstrating integer truncation
int squareInt(int x) {
    return x * x;
}

int main() {
    int leg1 = 3;
    int leg2 = 4;

    // Argument coercion: int promoted to double automatically
    double hyp = computeHypotenuse(leg1, leg2);
    std::cout << "Hypotenuse: " << hyp << "\n";

    // Narrowing coercion: 4.9 truncated to 4
    double val = 4.9;
    int result = squareInt(static_cast<int>(val));
    std::cout << "Square of truncated " << static_cast<int>(val) << ": " << result << "\n";

    return 0;
}
